folders={'v2_full_noise':V2/'runs/noisy_candidate','v3_x_noise_masked':V3/'runs/noisy_candidate'}
assert all((p/'report.json').exists() and read(p/'report.json')['completed'] for p in folders.values()), 'Await completed native reports; no partial results analysis'
files=[p for f in folders.values() for p in f.iterdir() if p.is_file()]+[V3/'experiment.json',V3/'cpu_verification.json']
before={str(p):sha(p) for p in files}
result={'scope':'one predeclared noNN axis attribution experiment, no training; exploration failures allowed and90% noisy gate is not a prerequisite to PPO','denominator':{'attempts_per_condition':128,'note_opportunities':384,'failed_attempts_retained':True},'runs':{},'paired':{}}
episodes={}
for name,p in folders.items():
 ev=read(p/'evaluation.json');eps=sorted(ev['episodes'],key=lambda e:e['env_id']);episodes[name]=eps;report=read(p/'report.json');pins=read(p/'inputs_after.json');meta=read(p/'trace_metadata.json');a=np.load(p/'trace_env0_episode0.npz');force=np.linalg.norm(a['net_body_force_n'][:,meta['body_names'].index('human/LH:index3')],axis=1)
 r={'attempts':len(eps),'env_ids':[e['env_id'] for e in eps],'acceptance':ev['acceptance'],'reward_sum':sum(e['reward'] for e in eps),'cost_sum':sum(e['cost'] for e in eps),'reward_components':{k:sum(e['reward_components'][k] for e in eps) for k in eps[0]['reward_components']},'report':report,'input_pin_count':len(pins['input_pins']),'changed_paths':pins['changed_paths'],'per_note':[]}
 for i,(idx,lo,hi) in enumerate([(4,3,3.1703),(7,3.952,4.7299),(8,5.3568,5.7051)]):
  ns=[e['notes'][i] for e in eps];k=(a['time_s']>=lo)&(a['time_s']<=hi);bad=k&~a['candidate'][:,i]
  r['per_note'].append({'source_index':idx,'achieved':sum(n['achieved'] for n in ns),'released':sum(n['released'] for n in ns),'achieved_and_A_released':sum(e['notes'][i]['achieved'] and e['notes'][0]['released'] for e in eps),'failed_and_A_unreleased':sum(not e['notes'][i]['achieved'] and not e['notes'][0]['released'] for e in eps),'clean_mean':float(np.mean([n['clean_fraction'] for n in ns])),'wrong_mean':float(np.mean([n['audible_wrong_fraction'] for n in ns])),'missing_mean':float(np.mean([n['missing_fraction'] for n in ns])),'best_clean_streak_mean_s':float(np.mean([n['note']['best_clean_streak'] for n in ns])),'best_clean_streak_min_s':min(n['note']['best_clean_streak'] for n in ns),'env0_audible_rows':int(k.sum()),'env0_candidate_miss_rows':int(bad.sum()),'env0_unloaded_miss_rows':int((bad&(force<.01)).sum())})
 result['runs'][name]=r
old,new=episodes.values();assert [e['env_id'] for e in old]==[e['env_id'] for e in new]==list(range(128))
def contingency(a,b):return {'both':sum(x and y for x,y in zip(a,b)),'v2_only':sum(x and not y for x,y in zip(a,b)),'v3_only':sum(not x and y for x,y in zip(a,b)),'neither':sum(not x and not y for x,y in zip(a,b))}
result['paired']['all3']=contingency([e['achieved'] for e in old],[e['achieved'] for e in new]);result['paired']['A_release']=contingency([e['notes'][0]['released'] for e in old],[e['notes'][0]['released'] for e in new]);result['paired']['per_note']=[]
for i,idx in enumerate([4,7,8]):
 dif=np.array([b['notes'][i]['clean_fraction']-a['notes'][i]['clean_fraction'] for a,b in zip(old,new)]);sd=np.array([b['notes'][i]['note']['best_clean_streak']-a['notes'][i]['note']['best_clean_streak'] for a,b in zip(old,new)])
 result['paired']['per_note'].append({'source_index':idx,'achievement':contingency([e['notes'][i]['achieved'] for e in old],[e['notes'][i]['achieved'] for e in new]),'clean_delta_mean':float(dif.mean()),'clean_improved':int((dif>1e-12).sum()),'clean_worsened':int((dif< -1e-12).sum()),'clean_unchanged':int((abs(dif)<=1e-12).sum()),'streak_delta_mean_s':float(sd.mean())})
a=np.load(folders['v2_full_noise']/'reference_noise4.npz');b=np.load(folders['v3_x_noise_masked']/'reference_noise4.npz');m2=read(folders['v2_full_noise']/'trace_metadata.json');m3=read(folders['v3_x_noise_masked']/'trace_metadata.json')
noise={'full128x4_original_stream_sha_v2':m2['noise_stream_sha256'],'full128x4_original_stream_sha_v3':m3['noise_stream_sha256'],'full_stream_hash_equal':m2['noise_stream_sha256']==m3['noise_stream_sha256'],'saved_env0to3_rows':len(a['env_id']),'same_env_clock_rows':bool(np.array_equal(a['env_id'],b['env_id']) and np.array_equal(a['start_clock'],b['start_clock'])),'original_scaled_noise_byte_exact':a['scaled_noise'].tobytes()==b['scaled_noise'].tobytes(),'applied_col0_allzero':bool((b['applied_noise'][:,0]==0).all()),'applied_other3_byte_exact':b['applied_noise'][:,1:].tobytes()==a['scaled_noise'][:,1:].tobytes(),'raw_noisy_goal_other3_byte_exact':b['raw_noisy_goal'][:,1:].tobytes()==a['raw_noisy_goal'][:,1:].tobytes(),'raw_reference_byte_exact':a['raw_reference'].tobytes()==b['raw_reference'].tobytes(),'draw_scope':'full128x4 hash from runtime; saved samples env0..3 only; all4 draws retained, only application of column0 masked'}
result['noise_identity']=noise
dump('analysis.json',result)
after={str(p):sha(p) for p in files};checks={'input_sha_unchanged':before==after,'all128_denominator':all(r['attempts']==128 for r in result['runs'].values()),'paired_env_ids_exact128':len(old)==len(new)==128,'nine_reward_components':all(len(r['reward_components'])==9 for r in result['runs'].values()),'closed_and_source_pins_unchanged':all(r['report']['closed'] and not r['changed_paths'] for r in result['runs'].values()),'fullnoise_hash_equal':noise['full_stream_hash_equal'],'original_saved_noise_exact':noise['original_scaled_noise_byte_exact'],'applied0masked_other3exact':noise['applied_col0_allzero'] and noise['applied_other3_byte_exact'] and noise['raw_noisy_goal_other3_byte_exact'],'paired_sums128':sum(result['paired']['all3'].values())==128}
dump('verification.json',{'all_checks_passed':all(checks.values()),'checks':checks,'input_sha256_before':before,'input_sha256_after':after,'new_GPU_runs':0,'NN_created':0,'training_steps':0});assert all(checks.values())
fig,axes=plt.subplots(1,3,figsize=(14,4));x=np.arange(3)
for i,(name,r) in enumerate(result['runs'].items()):
 for ax,key,scale in zip(axes,['achieved','clean_mean','best_clean_streak_mean_s'],[100/128,100,1]):ax.bar(x+(i-.5)*.35,[n[key]*scale for n in r['per_note']],.35,label=name)
for ax,title in zip(axes,['Achievement /128 (%)','Mean clean fraction (%)','Mean best continuous clean streak (s)']):ax.set_xticks(x,['A4','B7','B8']);ax.set_title(title);ax.grid(axis='y',alpha=.2);ax.legend(fontsize=7)
fig.tight_layout();fig.savefig(OUT/'paired_performance.png',dpi=160);plt.close(fig)
print(json.dumps({'runs':{n:r['acceptance'] for n,r in result['runs'].items()},'paired':result['paired'],'noise':noise},ensure_ascii=False,indent=2))
lines=['# index1_x 잡음 mask 단일실험 결과','','index1_x에 가하는 잡음만0으로한V3는 원4성분잡음V2보다 전체3음달성이34→5/128로낮아졌다. 이mask를개선안으로채택하지않는다. 일부시도는좋아졌지만지속접촉은전반적으로악화했다. 이것은축을동결할근거도, index1_x잡음이항상필수라는증거도아니다.','','## 동일draw의실제128쌍','','각조건은원128시도·384음전체분모를유지했다. V2/V3의동일env_id를짝지었다. full128×4 Normal draw hash는모두`'+noise['full128x4_original_stream_sha_v2']+'`이며,저장env0..3의1416행scaled_noise는byte-exact다. V3는원4draw를모두소비하고적용col0만0이다. 다른3성분applied_noise와raw_noisy_goal은V2와byte-exact,원raw_reference도동일하다. 전체128draw의동일성은실행metadata hash,저장샘플동일성은NPZ bytes로구분검증했다.','','| 조건 | A4/B7/B8 달성(각128) | 전체3음 | A해제 | 물리/손목실패 |','|---|---|---:|---:|---|']
for n,r in result['runs'].items():lines.append(f"| {n} | {'/'.join(str(v['achieved']) for v in r['per_note'])} | {r['acceptance']['all3_achieved_fraction']*128:.0f}/128 | {r['per_note'][0]['released']}/128 | {r['acceptance']['physical_failures']}/{r['acceptance']['wrist_failures']} |")
lines+=['','| 쌍별달성 | 둘다 | V2만 | V3만 | 둘다미달 |','|---|---:|---:|---:|---:|']
for name,c in [('전체3음',result['paired']['all3']),('A해제',result['paired']['A_release'])]+[(str(n['source_index']),n['achievement']) for n in result['paired']['per_note']]:lines.append(f"| {name} | {c['both']} | {c['v2_only']} | {c['v3_only']} | {c['neither']} |")
lines+=['','전체3음성공전이: 원V2성공34중33이V3에서미달했고1만유지했다. 원V2미달94중4가V3에서새로성공했다. 따라서모든개별시도에동일한방향으로작용한것은아니다.','','## 연속clean과해제교차','','| 조건/음 | mean clean | mean wrong | mean missing | 최장연속clean 평균(s) | 해당음달성 AND A해제 | 해당음미달 AND A미해제 |','|---|---:|---:|---:|---:|---:|---:|']
for name,r in result['runs'].items():
 for n in r['per_note']:lines.append(f"| {name}/{n['source_index']} | {n['clean_mean']:.9f} | {n['wrong_mean']:.9f} | {n['missing_mean']:.9f} | {n['best_clean_streak_mean_s']:.9f} | {n['achieved_and_A_released']}/128 | {n['failed_and_A_unreleased']}/128 |")
lines+=['','B7연속clean 평균은0.336557→0.153453초로0.183103초줄었다. 원필요연속길이0.31116초에비해평균clean만으로달성여부를설명할수없다. B7 clean은36쌍개선/91악화/1동일이고달성은53쌍상실/4쌍획득이다. A4 mean clean은거의같지만달성54→45로낮아져연속성의중요성을보인다.','','env0의audible저장끝점candidate누락은V2의1/6/4개에서V3의2/7/4개다. 모두exported distal합력<0.01N의unloaded flag와겹친다. 대표env0만으로전체128실패원인이나pair별무접촉을확정하지않는다. net body force는접촉파트너·벡터상쇄·실제현압력·음향을분리하지못한다. 원240Hz판정은현재와직전candidate가모두참인구간만clean으로적산하며단절시연속streak를리셋한다. 저장60Hz끝점이전체240Hz이력은아니다.','','A해제latch는음끝후100ms안의true→false와ever를요구한다.97/128해제를나머지31개가실제로계속눌렀다는뜻으로해석하지않는다. B7/B8의별도released값과A해제gate도구분한다.','','![쌍별성과와연속성](paired_performance.png)','','## 보상9항과안전','','| 항목 | V2합 | V3합 |','|---|---:|---:|']
for k in result['runs']['v2_full_noise']['reward_components']:lines.append(f"| {k} | {result['runs']['v2_full_noise']['reward_components'][k]:.9f} | {result['runs']['v3_x_noise_masked']['reward_components'][k]:.9f} |")
lines+=['',f"원reward합은V2 {result['runs']['v2_full_noise']['reward_sum']:.9f}, V3 {result['runs']['v3_x_noise_masked']['reward_sum']:.9f}이다. 두cost합0,scene close완료,원핀변경0이다. 항목합과원total은float누적순서로작은반올림차이를가질수있다.",'','## 다음은학습된접촉강건성','','같은교사평균과나머지잡음을유지한한축mask가전반적으로악화했으므로이단일실험을마치고다른축mask·std/각도grid를이어가지않는다. 실제load/clean단절을단순히잡음문제로만보거나탐색을금지할근거가없다. 탐색이실패를만드는것은학습중허용되는현상이며 **noisy90%성공은PPO시작의필수조건이아니다**. 기존noisy gate실패는진단결론으로남기고학습시작계약과혼동하지않는다.','','다음짧은학습비교는결정론적124/128을확인한수정평균교사V2에서초기화한학습평균과원평균교사동작을명시예산으로비교하는것이합리적이다. 원4축분포/가동범위·실제접촉기준·effort cap·물리·보상9항을유지하고상태/표면오차에따라유한한press/hold/해제보정을학습한다. 교사평균을정책초기평균또는명시적인학습residual기준으로쓰는계약은구현전에확인해야하며무작위평균정책을교사보정으로부르지않는다. 평가에는훈련전후deterministic128과같은원noise128의음별clean/최장연속streak/실제하중/해제/실패를함께기록한다. 탐색std나평가gate를결과에맞춰낮추지않고훈련소모/실제업데이트도공개한다. 이분석에서는NN/PPO/새GPU를실행하지않았다.','','index1_x잡음이일부경로에서접촉을도왔을가능성은있지만, 네축이동시에작용하는비선형동역학에서특정axis가필수라는주장이나preload방향/크기를정하는근거가아니다. 물리적preload는후속학습의가능한유한접촉여유가설이며정적plane깊이를압력으로대체하거나접촉기준을완화하지않는다.','','## 재현과무결성','',f"analysis.json은원128분모·쌍별전이·음별연속streak/해제교차·보상9항·잡음동일성을보존한다. verification.json은입력{len(files)}파일의전후SHA256과실제{len(checks)}개자체검사통과를기록한다. analyze.py는CPU분석만수행하며원자료·활성소스·봉인입력은수정하지않았다."]
(OUT/'RESULTS.md').write_text('\n'.join(lines)+'\n')
